import functools


def _make_key(args, kwargs):
    """Build a hashable cache key from positional and keyword arguments.

    Returns None if the arguments cannot be hashed (such calls run without
    caching). Keyword argument order does not affect the key.
    """
    try:
        return args, tuple(sorted(kwargs.items()))
    except TypeError:
        return None


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _make_key(args, kwargs)
        if key is not None:
            if key in cache:
                stats["hits"] += 1
                return cache[key]
            stats["misses"] += 1
        result = fn(*args, **kwargs)
        if key is not None:
            cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
